    final Loan loanForProcessing = Mockito.mock(Loan.class);
    when(loanForProcessing.getId()).thenReturn(loanId);
    doThrow(new MultiException(Collections.singletonList(new RuntimeException()))).when(loanAccrualsProcessingService).addPeriodicAccruals(any(LocalDate.class), eq(loanForProcessing));
