    List<LoanAccountLock> accountLocks = List.of(1L, 2L, 3L, 4L, 5L).stream().map(l -> new LoanAccountLock(l, LockOwner.LOAN_COB_CHUNK_PROCESSING, LocalDate.of(2023, 7, 25))).toList();
