public void testLoanItemReaderMultiThreadRead() throws Exception {
    // given
    ThreadLocalContextUtil.setTenant(new FineractPlatformTenant(1L, "test", "test", "UTC", null));
    LoanItemReader loanItemReader = new LoanItemReader(loanRepository, retrieveLoanIdService, customJobParameterResolver, loanLockingService);
    when(stepExecution.getExecutionContext()).thenReturn(executionContext);
    LoanCOBParameter loanCOBParameter = new LoanCOBParameter(1L, 100L);
    when(executionContext.get(LoanCOBConstant.LOAN_COB_PARAMETER)).thenReturn(loanCOBParameter);
    when(retrieveLoanIdService.retrieveAllNonClosedLoansByLastClosedBusinessDateAndMinAndMaxLoanId(loanCOBParameter, false)).thenReturn(new ArrayList<>(IntStream.rangeClosed(1, 100).boxed().map(Long::valueOf).toList()));
    List<LoanAccountLock> accountLocks = IntStream.rangeClosed(1, 100).boxed().map(Long::valueOf).map(l -> new LoanAccountLock(l, LockOwner.LOAN_COB_CHUNK_PROCESSING, LocalDate.of(2023, 7, 25))).toList();
    when(loanLockingService.findAllByLoanIdInAndLockOwner(IntStream.rangeClosed(1, 100).boxed().map(Long::valueOf).toList(), LockOwner.LOAN_COB_CHUNK_PROCESSING)).thenReturn(accountLocks);
    when(loanRepository.findById(anyLong())).thenReturn(Optional.of(loan));
    // when + then
    loanItemReader.beforeStep(stepExecution);
    ExecutorService executorService = Executors.newFixedThreadPool(10);
    for (int i = 1; i <= 100; i++) {
        Future<?> notUsed = executorService.submit(() -> {
            try {
                Loan myLoan = loanItemReader.read();
                Assertions.assertEquals(loan, myLoan);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        });
    }
    executorService.shutdown();
    boolean b = executorService.awaitTermination(5L, TimeUnit.SECONDS);
    Assertions.assertEquals(true, b, "Executor did not terminate successfully");
    // verify that this was called 100times, and for each loan it was called exactly once
    for (long i = 1; i <= 100; i++) {
        verify(loanRepository, times(1)).findById(i);
    }
    Mockito.verifyNoMoreInteractions(loanRepository);
}

