        verify(loanTransactionRepository, never()).saveAndFlush(any(LoanTransaction.class));
        verify(businessEventNotifierService, never()).notifyPostBusinessEvent(any(LoanAccrualTransactionCreatedBusinessEvent.class));
    }
}

